def initialize_opening_valuation(apps, schema_editor):
    """Preserve existing stock quantity without inventing historical cost."""
    connection = schema_editor.connection
    snapshot = rls.read_scope(connection)
    rls.set_staff_scope(connection)
    try:
        balance_model = apps.get_model("operations", "StockBalance")
        layer_model = apps.get_model("operations", "InventoryCostLayer")
        for balance in balance_model.objects.all().iterator():
            balance.unknown_cost_quantity = balance.quantity
            balance.save(update_fields=["unknown_cost_quantity"])
            if balance.quantity:
                layer_model.objects.create(
                    business_id=balance.business_id,
                    location_id=balance.location_id,
                    product_id=balance.product_id,
                    layer_type="OPENING",
                    source_type="OPENING_VALUATION",
                    source_id=balance.id,
                    quantity_delta=balance.quantity,
                    costed_quantity_delta=Decimal("0"),
                    unknown_cost_quantity_delta=balance.quantity,
                    value_delta_minor=0,
                    occurred_at=balance.updated_at,
                )
    finally:
        rls.restore_scope(connection, snapshot)


